noten = {"Mathe": 2}
noten["POS"] = 1      # neu hinzufügen
noten["Mathe"] = 3    # überschreiben
del noten["POS"]      # löschen
print(noten)          # {'Mathe': 3}

preise = {"Semmel": 0.5, "Milch": 1.3}

if "Butter" in preise:
    print(preise["Butter"])
else:
    print("Butter gibt es nicht")

print(preise.get("Butter"))       # None
print(preise.get("Butter", 0))    # 0

lager = {"Äpfel": 12, "Birnen": 0, "Bananen": 7}

for obst, anzahl in lager.items():
    print(f"{obst}: {anzahl} Stück")

print(sum(lager.values()))   # 19

woerter = "ja nein ja vielleicht ja".split()
zaehler = {}
for wort in woerter:
    zaehler[wort] = zaehler.get(wort, 0) + 1
print(zaehler)   # {'ja': 3, 'nein': 1, 'vielleicht': 1}

